import{_ as a,a as c}from"./chunks/npu_3510_hw_arch_sync.ByinXTj7.js";import{_ as n,a as _}from"./chunks/intra_core_parallel_pipeline_execution_timing.BdSPSiwi.js";import{_ as t,o as d,a as e,b as p}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"核内同步能力概述","link":"/api/SIMD-API/c_api/sync/intra_core_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/intra_core_sync_overview.md","filePath":"api/SIMD-API/c_api/sync/intra_core_sync_overview.md","outlineHeaders":[{"level":2,"title":"为什么需要核内同步","slug":"为什么需要核内同步","link":"#为什么需要核内同步"},{"level":2,"title":"硬件流水类型","slug":"硬件流水类型","link":"#硬件流水类型"},{"level":2,"title":"核内同步分类","slug":"核内同步分类","link":"#核内同步分类"},{"level":2,"title":"什么时候需要开发者手动插入同步","slug":"什么时候需要开发者手动插入同步","link":"#什么时候需要开发者手动插入同步"}],"lastUpdated":1788329934000}'),o={name:"api/SIMD-API/c_api/sync/intra_core_sync_overview.md"};function E(P,s,l,i,I,r){return d(),e("div",null,[...s[0]||(s[0]=[p('<div><article class="markdown-body"><h1>核内同步能力概述</h1><h2 id="为什么需要核内同步">为什么需要核内同步<a class="header-anchor" href="#为什么需要核内同步">​</a></h2><p>AI Core内部的执行单元（如MTE2搬运单元、Vector计算单元等）以异步并行的方式运行，在读写同一存储资源时可能存在数据依赖关系。为确保数据一致性及计算正确性，需通过同步控制协调操作时序。</p><div data-filter="950"><p>针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构3510</a>，硬件架构图如下，高亮部分展示了并行执行的计算单元和搬运单元。</p><p><strong>图1</strong> NPU架构3510架构图<br><img src="'+a+'" alt></p></div><div data-filter="A3,910b"><p>针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构2201</a>，硬件架构图如下，高亮部分展示了并行执行的计算单元和搬运单元。</p><p><strong>图2</strong> NPU架构2201架构图<br><img src="'+c+'" alt></p></div><p>下图示例描述了一个常见的Vector计算数据流：</p><ol><li>先通过DMA执行单元将数据从GM搬入到Local Memory；</li><li>进行计算；</li><li>然后再通过DMA执行单元将计算结果从Local Memory搬出到GM。</li></ol><p><strong>图3</strong> Vector计算数据流示意图<br><img src="'+n+'" alt></p><p>四个执行单元Scalar、Vector、DMA（MTE2）、DMA（MTE3）并行执行，若访问同一片Local Memory，需要同步机制来控制它们的访问时序：保证先搬入Local Memory后再计算，计算完成后再搬出。</p><p><strong>图4</strong> 核内并行流水执行时序示意图<br><img src="'+_+`" alt></p><h2 id="硬件流水类型">硬件流水类型<a class="header-anchor" href="#硬件流水类型">​</a></h2><p>AI Core内部并行的指令流水类型和解释如下所示：</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>不同的硬件架构，每一种硬件流水类型包含的具体流水会有所差异，详细介绍请参考<a href="../../../../guide/programming_guide/advanced_programming/hardware_implementation/hardware_implementation.html">硬件实现</a>章节。</p></div><p><strong>表1</strong> 指令流水类型和相关说明</p><table><thead><tr><th>流水类型</th><th>含义</th></tr></thead><tbody><tr><td>PIPE_S</td><td>标量流水线，使用标量访存语句或标量计算接口访问GM、片上存储地址时为此流水</td></tr><tr><td>PIPE_V</td><td>矢量计算流水及部分硬件架构下的L0C Buffer-&gt;UB数据搬运流水</td></tr><tr><td>PIPE_M</td><td>矩阵计算流水</td></tr><tr><td>PIPE_MTE1</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer数据搬运流水</td></tr><tr><td>PIPE_MTE2</td><td>GM-&gt;L1 Buffer、GM-&gt;UB等数据搬运流水</td></tr><tr><td>PIPE_MTE3</td><td>UB-&gt;GM等数据搬运流水</td></tr><tr><td>PIPE_FIX</td><td>L0C Buffer-&gt;GM、L0C Buffer-&gt;L1 Buffer等数据搬运流水</td></tr></tbody></table><h2 id="核内同步分类">核内同步分类<a class="header-anchor" href="#核内同步分类">​</a></h2><p>对上述核内并行流水的同步控制分为以下几种：</p><ul><li>多流水同步：同一核内具有数据依赖的不同类型流水指令之间的同步。 <ul><li>通过<a href="asc_sync_notify.html">asc_sync_notify</a>/<a href="asc_sync_wait.html">asc_sync_wait</a>接口进行不同流水线间的同步控制。在<code>asc_sync_notify</code>/<code>asc_sync_wait</code>的指令中，可以指定一对指令流水（源流水与目的流水）先后执行的关系，表示两个指令流水之间完成一组“锁”机制，其作用原理为： <ul><li><code>asc_sync_notify</code>：当源流水的前序指令的所有读写操作都完成之后，当前指令开始执行，并将硬件中的对应标志位设置为1。</li><li><code>asc_sync_wait</code>：当目的流水执行到该指令时，如果发现硬件中对应标志位为0，目的流水的后续指令将一直被阻塞；如果发现硬件中对应标志位为1，则将硬件中对应标志位设置为0，同时目的流水的后续指令开始执行。</li></ul></li></ul><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，新增<a href="asc_lock.html">asc_lock</a>/<a href="asc_unlock.html">asc_unlock</a>接口进行不同流水线间的同步控制。通过<code>Lock</code>锁定指定流水（阻塞后续指令），再通过<code>Unlock</code>释放流水，来完成流水间的同步依赖。 <ul><li><code>asc_lock</code>：根据<code>mutex_id</code>获取Mutex，若Mutex已被锁定，将阻塞后续指定流水指令队列，直到前序指令中对应<code>mutex_id</code>的Mutex被<code>asc_unlock</code>。</li><li><code>asc_unlock</code>：当前流水的前置指令退出后，根据<code>mutex_id</code>释放对应Mutex。</li></ul></li><li>相较于<code>asc_sync_notify</code>/<code>asc_sync_wait</code>同步机制，使用<code>asc_lock</code>/<code>asc_unlock</code>接口有以下优势： <ul><li><p>内聚性更强，使用时与其它流水线解耦，可以简化反向同步。以<code>PIPE_MTE2</code>与<code>PIPE_V</code>之间同步为例，对比如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// asc_sync_notify/asc_sync_wait机制</span>
<span class="n">For</span><span class="w"> </span><span class="n">i</span><span class="o">=</span><span class="mi">0</span><span class="o">:</span><span class="mi">100</span>
<span class="w">   </span><span class="k">if</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="mi">0</span><span class="o">:</span>
<span class="w">         </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">   </span><span class="n">endif</span>
<span class="w">   </span><span class="c1">// MTE2指令</span>
<span class="w">   </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">   </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">   </span><span class="c1">// PIPE_V指令</span>
<span class="w">   </span><span class="k">if</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">99</span><span class="o">:</span>
<span class="w">         </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">   </span><span class="n">endif</span>
<span class="n">endFor</span>

<span class="c1">// asc_lock/asc_unlock机制</span>
<span class="n">For</span><span class="w"> </span><span class="n">i</span><span class="o">=</span><span class="mi">0</span><span class="o">:</span><span class="mi">100</span>
<span class="w">   </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="w">   </span><span class="c1">// MTE2指令</span>
<span class="w">   </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="w">   </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="w">   </span><span class="c1">// PIPE_V指令</span>
<span class="w">   </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="n">endFor</span>
</code></pre></div></li><li><p>可以使用更多的同步信号量：<code>asc_sync_notify</code>/<code>asc_sync_wait</code>的入参<code>EVENT_ID0</code>为同步ID，取值范围为[0, 7]；而<code>asc_lock</code>/<code>asc_unlock</code>的入参<code>mutex_id</code>取值范围为[0, 31]。</p></li></ul></li></ul></div></li><li>单流水同步：同一核内具有数据依赖的相同类型流水指令之间的同步。通过<a href="asc_sync_pipe.html">asc_sync_pipe</a>接口进行相同流水线间的同步控制。同一流水中虽然指令是顺序执行，但并不意味着后一条指令开始执行时前一条指令执行结束。<code>asc_sync_pipe</code>指令可以保证前序指令中所有数据读写全部完成，后序指令才开始执行。注意该接口不支持PIPE_S单流水的同步。</li><li>通过<a href="asc_sync_data_barrier.html">asc_sync_data_barrier</a>接口阻塞后续指令的执行，直到此前已发出但尚未完成的内存访问指令全部执行完成。开发者通过<code>arg</code>参数指定屏障作用的内存范围，确保屏障前后的内存访问指令按预期顺序完成。</li></ul><div data-filter="A3,910b"><p>以<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构2201</a>为例，该硬件架构下所有合法的核内同步组合如<a href="#aic_intra_core_sync_combinations">表2</a>和<a href="#aiv_intra_core_sync_combinations">表3</a>所示。其中，“不涉及”表示硬件层面不存在此种同步组合，“暂无应用场景”表示存在此种同步组合，但在实际开发场景中暂不需要使用。</p><p><span id="aic_intra_core_sync_combinations"></span></p><p><strong>表2</strong> AIC中所有合法的核内同步组合</p><table><thead><tr><th>源流水/目的流水</th><th><code>PIPE_S</code></th><th><code>PIPE_M</code></th><th><code>PIPE_MTE1</code></th><th><code>PIPE_MTE2</code></th><th><code>PIPE_MTE3</code></th><th><code>PIPE_FIX</code></th></tr></thead><tbody><tr><td><code>PIPE_S</code></td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td></tr><tr><td><code>PIPE_M</code></td><td>不涉及</td><td><code>asc_sync_pipe(PIPE_M)</code></td><td><code>asc_sync_notify(PIPE_M, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_M, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_MTE2, EVENT_ID0)</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_M, PIPE_FIX, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_FIX, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE1</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE1)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_MTE3, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_FIX, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_FIX, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE2</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE2)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code></td><td>暂无应用场景</td></tr><tr><td><code>PIPE_MTE3</code></td><td>不涉及</td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE3)</code></td><td>暂无应用场景</td></tr><tr><td><code>PIPE_FIX</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_FIX, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_FIX, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_FIX, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_FIX, PIPE_MTE1, EVENT_ID0)</code></td><td>暂无应用场景</td><td>暂无应用场景</td><td><code>asc_sync_pipe(PIPE_FIX)</code></td></tr></tbody></table><p><span id="aiv_intra_core_sync_combinations"></span></p><p><strong>表3</strong> AIV中所有合法的核内同步组合</p><table><thead><tr><th>源流水/目的流水</th><th><code>PIPE_S</code></th><th><code>PIPE_V</code></th><th><code>PIPE_MTE2</code></th><th><code>PIPE_MTE3</code></th></tr></thead><tbody><tr><td><code>PIPE_S</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_S, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_S, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_S, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_V</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_V)</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE2</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE2)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td><code>PIPE_MTE3</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE3)</code></td></tr></tbody></table></div><h2 id="什么时候需要开发者手动插入同步">什么时候需要开发者手动插入同步<a class="header-anchor" href="#什么时候需要开发者手动插入同步">​</a></h2><p>C API编程方式下所有的同步均需开发者手动管理。</p></article></div>`,1)])])}const V=t(o,[["render",E]]);export{h as __pageData,V as default};
